<template><view class="page"><view class="cover"><image src="https://images.unsplash.com/photo-1464278533981-50106e6176b1?w=1200" mode="aspectFill"/><view class="cover-overlay"><view><text class="tag tag-dark">川西</text><text class="tag tag-dark">5天4夜</text><text class="tag tag-dark">3680 积分</text></view><view class="big">川西雪山轻徒步</view></view></view><view class="content"><view class="btn-row"><view class="btn btn-ghost fav-action" :class="{selected:favorited}" @click="toggleFavorite">{{favorited?'♥ 已收藏路线':'♡ 收藏路线'}}</view><view class="btn btn-green target-action" :class="{selected:targeted}" @click="toggleTarget">{{targeted?'✓ 已加入上岸心愿':'🎓 设为上岸目标'}}</view></view><view class="section-title">一路向雪山</view><view class="timeline"><view class="timeline-item" v-for="d in days" :key="d.day"><b>{{d.day}} · {{d.title}}</b><view class="sub">{{d.desc}}</view><image class="day-img" :src="d.img" mode="aspectFill"/></view></view><view class="card"><view class="card-title">住进风景里</view><image class="hotel" src="https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1000" mode="aspectFill"/><view class="list-title">四钻设计师酒店 · 雪山景观房</view><view class="sub">双人标间 / 独立卫浴 / 含早餐</view></view><view class="card"><view class="card-title">积分权益说明</view><view class="fee"><text>交通、住宿、门票、领队、保险</text><text class="green">积分已包含</text></view><view class="fee"><text>个人餐饮、单房差、旅拍妆造</text><text class="orange">积分自理</text></view></view><view class="section-title">上岸学员怎么说</view><view class="card"><view class="list-item"><view class="avatar">鹿</view><view class="list-main"><b>小鹿学姐</b><view class="sub">上岸厦大 · 2026 届</view></view><text class="orange">★★★★★</text></view><view class="review">“不是赶景点，是认真看一座山。领队很懂年轻人的节奏，毕业旅行选这里很值。”</view></view></view><view class="fixed-action"><view class="btn-row"><view class="btn btn-ghost" @click="go('/pages/custom/params')">智能匹配相似路线</view><view class="btn btn-primary" @click="go('/pages/custom/manual')">人工深度定制</view></view></view></view></template>
<script setup>import{ref}from'vue';import{trackPreference}from'../../utils/api.js';const routeName='川西雪山轻徒步',routeId=1,favorited=ref((uni.getStorageSync('favoriteRoutes')||[]).includes(routeName)),targeted=ref((uni.getStorageSync('targetRoutes')||[]).includes(routeName));const toggleStored=(key,state)=>{const set=new Set(uni.getStorageSync(key)||[]);state.value?set.delete(routeName):set.add(routeName);state.value=!state.value;uni.setStorageSync(key,[...set])};const toggleFavorite=()=>{toggleStored('favoriteRoutes',favorited);trackPreference({type:'route',key:routeId,name:routeName,action:favorited.value?'favorite_add':'favorite_remove',score:favorited.value?3:-3});uni.showToast({title:favorited.value?'已收藏这段旅程':'已取消收藏',icon:'none'})};const toggleTarget=()=>{toggleStored('targetRoutes',targeted);trackPreference({type:'route',key:routeId,name:routeName,action:targeted.value?'target_add':'target_remove',score:targeted.value?5:-5});uni.showToast({title:targeted.value?'已加入上岸心愿':'已移出上岸心愿',icon:'none'})};const days=[{day:'Day 1',title:'成都集合 · 青春碰面',desc:'入住市区酒店，领队见面会，自由探索成都夜色。',img:'https://images.unsplash.com/photo-1528127269322-539801943592?w=900'},{day:'Day 2',title:'四姑娘山 · 双桥沟',desc:'穿越雪山、森林与海子，傍晚入住藏式民宿。',img:'https://images.unsplash.com/photo-1464278533981-50106e6176b1?w=900'},{day:'Day 3-5',title:'墨石公园 · 鱼子西 · 返程',desc:'日落旅拍、非遗体验，在群山环抱中告别。',img:'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?w=900'}];const go=url=>uni.navigateTo({url});const toast=title=>uni.showToast({title,icon:'none'})</script><style scoped>.fav-action.selected{color:#f04452;background:#fff0f1}.target-action.selected{background:#e7f6f2;color:#078b7b}.day-img,.hotel{width:100%;height:280rpx;border-radius:22rpx;margin-top:16rpx}.hotel{margin-bottom:16rpx}.fee{display:flex;justify-content:space-between;padding:18rpx 0;border-bottom:1rpx solid #e7ebe7}.review{line-height:1.8;color:#586764;padding-top:20rpx}</style>
